/** Text of the print options in the Download dialog (`t.print`). */
const plural = (n: number, one: string, many: string): string => (n === 1 ? one : many)

export const print = {
  section: 'Print',
  preset: 'Print setup',
  presets: {
    screen: 'Screen',
    standard: 'Standard print',
    custom: 'Custom',
  },
  presetHints: {
    screen: 'No bleed, no marks',
    standard: '3 mm bleed and crop marks',
    custom: 'Set your own bleed',
  },
  bleed: 'Bleed',
  bleedRange: 'From 0 to 10 mm',
  bleedIn: (value: string, unit: string) => `= ${value} ${unit}`,
  bleedHelp: 'Artwork that continues past the page edge, so trimming leaves no white edge.',
  cropMarks: 'Crop marks',
  cropMarksHint: 'Thin lines in the margin that show where to cut.',
  summary: (pages: number, sizes: readonly string[], more: number) =>
    `${pages} ${plural(pages, 'page', 'pages')} · ${sizes.length + more} ${plural(sizes.length + more, 'size', 'sizes')}: ${sizes.join(', ')}${more > 0 ? ` and ${more} more` : ''}`,
  noPages: 'No pages selected',
  /** Short names of the print sizes, by size preset id. */
  paper: { a4: 'A4', a5: 'A5', a3: 'A3', letter: 'US Letter' } as Readonly<Record<string, string>>,
  sheet: (width: string, height: string, unit: string, extras: string) => `Each page is ${width} × ${height} ${unit} with ${extras}.`,
  sheetMixed: (extras: string) => `Each page grows by the ${extras}.`,
  extras: { both: 'bleed and crop marks', bleed: 'bleed', marks: 'crop marks' },
  colour: 'Colours are exported as RGB, as they look on screen. Ask your printer whether they accept RGB files; there is no CMYK conversion.',
  engineServer: 'Printed on the server: text stays text, graphics stay vector, links stay clickable.',
  engineClient: 'Made in your browser: every page is a 300 dpi picture, so text is not selectable.',
  preview: 'Schematic, not to scale',
  previewAlt: (bleed: string, marks: boolean) => `Page layout: trim line${bleed ? `, ${bleed} bleed around it` : ''}${marks ? ', crop marks in the margin' : ''}`,
  legendTrim: 'Trim',
  legendBleed: 'Bleed',
  legendMarks: 'Crop marks',
  cancel: 'Cancel',
  retry: 'Try again',
  retryIn: (seconds: number) => `Try again in ${seconds} s`,
  stage: {
    rendering: 'Preparing pages…',
    uploading: 'Sending to the print service…',
    printing: 'Printing the PDF…',
  },
  cancelled: 'Download cancelled',
  problems: {
    busy: 'The print service is busy with other downloads.',
    busyHint: 'It is free again in a few seconds.',
    timeout: 'Printing took too long and was stopped.',
    timeoutHint: 'Try fewer pages at a time, or use the standard PDF.',
    unavailable: 'The print service is not available right now.',
    unavailableHint: 'The standard PDF is made in your browser and still works.',
    disabled: 'Print-quality PDF is turned off on this server.',
    disabledHint: 'Use the standard PDF instead.',
    failed: 'The print service could not make this PDF.',
    failedHint: 'Try again. If it keeps failing, use the standard PDF.',
    font: (detail: string) => `A font in this design could not be added to the PDF. ${detail}`,
    fontHint: 'Replace that font, or use the standard PDF.',
    pageHint: 'Remove anything unusual on that page, an imported graphic for example, or use the standard PDF.',
    tooLarge: 'This design is too large to print on the server.',
    tooLargeHint: 'Use smaller images, fewer pages at a time, or the standard PDF.',
    rateLimited: 'You have started many downloads in a short time.',
    signedOut: 'Your session has ended.',
    signedOutHint: 'Sign in again, then download again.',
    offline: 'We could not reach Doory. Check your connection and try again.',
    invalid: (detail: string) => `The print service did not accept this request. ${detail}`,
  },
} as const
